test_code:
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_pool() {
        let mut pool = MemoryPool::new(2, 64);
        let b1 = pool.acquire();
        assert!(b1.is_some());
        let b2 = pool.acquire();
        assert!(b2.is_some());
        assert!(pool.acquire().is_none());
        pool.release(b1.unwrap());
        assert!(pool.acquire().is_some());
    }
}
